/// @title Dividend-Paying Token Optional Interface
/// @author Roger Wu (https://github.com/roger-wu)
/// @dev OPTIONAL functions for a dividend-paying token contract.
interface DividendPayingTokenOptionalInterface {
  /// @notice View the amount of dividend in wei that an address can withdraw.
  /// @param user The address of a token holder.
  /// @return The amount of dividend in wei that `user` can withdraw.
  function withdrawableDividendOf(address user) external view returns(uint256);

  /// @notice View the amount of dividend in wei that an address has withdrawn.
  /// @param user The address of a token holder.
  /// @return The amount of dividend in wei that `user` has withdrawn.
  function withdrawnDividendOf(address user) external view returns(uint256);

  /// @notice View the amount of dividend in wei that an address has earned in total.
  /// @dev accumulativeDividendOf(user) = withdrawableDividendOf(user) + withdrawnDividendOf(user)
  /// @param user The address of a token holder.
  /// @return The amount of dividend in wei that `user` has earned in total.
  function accumulativeDividendOf(address user) external view returns(uint256);
}

