/// @title Dividend-Paying Token
/// @author Roger Wu (https://github.com/roger-wu)
/// @dev A mintable ERC20 token that allows anyone to pay and distribute ether
///  to token holders as dividends and allows token holders to withdraw their dividends.
///  Reference: the source code of PoWH3D: https://etherscan.io/address/0xB3775fB83F7D12A36E0475aBdD1FCA35c091efBe#code
contract DividendPayingToken is ERC20, Ownable, DividendPayingTokenInterface, DividendPayingTokenOptionalInterface {
  using SafeMath for uint256;
  using SafeMathUint for uint256;
  using SafeMathInt for int256;

  address public constant PAXG = address(0x45804880De22913dAFE09f4980848ECE6EcbAf78); //PAXG


  // With `MAGNITUDE`, we can properly distribute dividends even if the amount of received ether is small.
  // For more discussion about choosing the value of `MAGNITUDE`,
  //  see https://github.com/ethereum/EIPs/issues/1726#issuecomment-472352728
  uint256 constant internal MAGNITUDE = 2**128;

  uint256 internal magnifiedDividendPerShare;

  // About dividendCorrection:
  // If the token balance of a `_user` is never changed, the dividend of `_user` can be computed with:
  //   `dividendOf(_user) = dividendPerShare * balanceOf(_user)`.
  // When `balanceOf(_user)` is changed (via minting/burning/transferring tokens),
  //   `dividendOf(_user)` should not be changed,
  //   but the computed value of `dividendPerShare * balanceOf(_user)` is changed.
  // To keep the `dividendOf(_user)` unchanged, we add a correction term:
  //   `dividendOf(_user) = dividendPerShare * balanceOf(_user) + dividendCorrectionOf(_user)`,
  //   where `dividendCorrectionOf(_user)` is updated whenever `balanceOf(_user)` is changed:
  //   `dividendCorrectionOf(_user) = dividendPerShare * (old balanceOf(_user)) - (new balanceOf(_user))`.
  // So now `dividendOf(_user)` returns the same value before and after `balanceOf(_user)` is changed.
  mapping(address => int256) internal magnifiedDividendCorrections;
  mapping(address => uint256) internal withdrawnDividends;

  uint256 public totalDividendsDistributed;

  constructor (string memory DividendTokenName, string memory DividendTokensymbol) ERC20(DividendTokenName, DividendTokensymbol) {

  }

  function decimals () public pure override returns (uint8) {
        return 9;
    }


  function distributePAXGDividends(uint256 amount) public onlyOwner{
    require(totalSupply() > 0);

    if (amount > 0) {
      magnifiedDividendPerShare = magnifiedDividendPerShare.add(
        (amount).mul(MAGNITUDE) / totalSupply()
      );
      emit DividendsDistributed(msg.sender, amount);

      totalDividendsDistributed = totalDividendsDistributed.add(amount);
    }
  }

  /// @notice Withdraws the ether distributed to the sender.
  /// @dev It emits a `DividendWithdrawn` event if the amount of withdrawn ether is greater than 0.
  function withdrawDividend() public virtual override {
    _withdrawDividendOfUser(payable(msg.sender));
  }

  /// @notice Withdraws the ether distributed to the sender.
  /// @dev It emits a `DividendWithdrawn` event if the amount of withdrawn ether is greater than 0.
 function _withdrawDividendOfUser(address payable user) internal returns (uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
      withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
      emit DividendWithdrawn(user, _withdrawableDividend);
      bool success = IERC20(PAXG).transfer(user, _withdrawableDividend);

      if(!success) {
        withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
        return 0;
      }

      return _withdrawableDividend;
    }

    return 0;
  }


  /// @notice View the amount of dividend in wei that an address can withdraw.
  /// @param tokenOwner The address of a token holder.
  /// @return The amount of dividend in wei that `tokenOwner` can withdraw.
  function dividendOf(address tokenOwner) public view override returns(uint256) {
    return withdrawableDividendOf(tokenOwner);
  }

  /// @notice View the amount of dividend in wei that an address can withdraw.
  /// @param tokenOwner The address of a token holder.
  /// @return The amount of dividend in wei that `tokenOwner` can withdraw.
  function withdrawableDividendOf(address tokenOwner) public view override returns(uint256) {
    return accumulativeDividendOf(tokenOwner).sub(withdrawnDividends[tokenOwner]);
  }

  /// @notice View the amount of dividend in wei that an address has withdrawn.
  /// @param tokenOwner The address of a token holder.
  /// @return The amount of dividend in wei that `tokenOwner` has withdrawn.
  function withdrawnDividendOf(address tokenOwner) public view override returns(uint256) {
    return withdrawnDividends[tokenOwner];
  }


  /// @notice View the amount of dividend in wei that an address has earned in total.
  /// @dev accumulativeDividendOf(tokenOwner) = withdrawableDividendOf(tokenOwner) + withdrawnDividendOf(tokenOwner)
  /// = (magnifiedDividendPerShare * balanceOf(tokenOwner) + magnifiedDividendCorrections[tokenOwner]) / MAGNITUDE
  /// @param tokenOwner The address of a token holder.
  /// @return The amount of dividend in wei that `tokenOwner` has earned in total.
  function accumulativeDividendOf(address tokenOwner) public view override returns(uint256) {
    return magnifiedDividendPerShare.mul(balanceOf(tokenOwner)).toInt256Safe()
      .add(magnifiedDividendCorrections[tokenOwner]).toUint256Safe() / MAGNITUDE;
  }

  /// @dev Internal function that transfer tokens from one address to another.
  /// Update magnifiedDividendCorrections to keep dividends unchanged.
  /// @param from The address to transfer from.
  /// @param to The address to transfer to.
  /// @param value The amount to be transferred.
  function _transfer(address from, address to, uint256 value) internal virtual override {
    require(false);

    int256 _magCorrection = magnifiedDividendPerShare.mul(value).toInt256Safe();
    magnifiedDividendCorrections[from] = magnifiedDividendCorrections[from].add(_magCorrection);
    magnifiedDividendCorrections[to] = magnifiedDividendCorrections[to].sub(_magCorrection);
  }

  /// @dev Internal function that mints tokens to an account.
  /// Update magnifiedDividendCorrections to keep dividends unchanged.
  /// @param account The account that will receive the created tokens.
  /// @param value The amount that will be created.
  function _mint(address account, uint256 value) internal override {
    super._mint(account, value);

    magnifiedDividendCorrections[account] = magnifiedDividendCorrections[account]
      .sub( (magnifiedDividendPerShare.mul(value)).toInt256Safe() );
  }

  /// @dev Internal function that burns an amount of the token of a given account.
  /// Update magnifiedDividendCorrections to keep dividends unchanged.
  /// @param account The account whose tokens will be burnt.
  /// @param value The amount that will be burnt.
  function _burn(address account, uint256 value) internal override {
    super._burn(account, value);

    magnifiedDividendCorrections[account] = magnifiedDividendCorrections[account]
      .add( (magnifiedDividendPerShare.mul(value)).toInt256Safe() );
  }

  function _setBalance(address account, uint256 newBalance) internal {
    uint256 currentBalance = balanceOf(account);

    if(newBalance > currentBalance) {
      uint256 mintAmount = newBalance.sub(currentBalance);
      _mint(account, mintAmount);
    } else if(newBalance < currentBalance) {
      uint256 burnAmount = currentBalance.sub(newBalance);
      _burn(account, burnAmount);
    }
  }
}

// File: contracts/AIG.sol

pragma solidity 0.8.19;


contract AIG is ERC20, Ownable {
    using SafeMath for uint256;

    struct BuyFee {
        uint16 reward;
        uint16 marketing;
    }

    struct SellFee {
        uint16 reward;
        uint16 marketing;
        uint16 autoLP;
    }

    BuyFee public buyFee;
    SellFee public sellFee;

    IUniswapV2Router02 public uniswapV2Router;
    address public uniswapV2Pair;

    bool private swapping;

    uint16 private totalBuyFee;
    uint16 private totalSellFee;

    TOKENDividendTracker public dividendTracker;

    address private constant DEAD_WALLET = address(0xdead);
    uint256 private constant MAX_COOLDOWN_BLOCKS = 4;
    

    address private constant PAXG =
        address(0x45804880De22913dAFE09f4980848ECE6EcbAf78); //PAXG

    uint256 public swapTokensAtAmount = 2e5 * 1e9;
    uint256 public maxTxAmount;
    uint256 public maxWallet;
    uint256 public coolDownBlocks;

    address payable public marketingWallet = payable(0xb02f23bb6a1e04e504fF158166649D9667B5c14D); //marketing wallet
    address payable public lpWallet = payable(0xB067311e1C9c7F4d2600D48B65965423d8e3036B); //lp receiver wallet

    // use by default 300,000 gas to process auto-claiming dividends
    uint256 public gasForProcessing = 300000;

    // exlcude from fees and max transaction amount
    mapping(address => bool) private _isExcludedFromFees;
    mapping(address => uint256) private _lastTradeBlock;

    // store addresses that a automatic market maker pairs. Any transfer *to* these addresses
    // could be subject to a maximum transfer amount
    mapping(address => bool) public automatedMarketMakerPairs;


    event UpdateUniswapV2Router(
        address indexed newAddress,
        address indexed oldAddress
    );

    event ExcludeFromFees(address indexed account, bool isExcluded);
    
    event SetAutomatedMarketMakerPair(address indexed pair, bool indexed value);

    event CoolDownBlocksUpdated (uint256 newValue);

    event WalletsUpdated(
        address indexed newMarketingWallet,
        address indexed newLiquidityWallet
    );

    event GasForProcessingUpdated(
        uint256 indexed newValue,
        uint256 indexed oldValue
    );

    event SwapAndLiquify(
        uint256 tokensSwapped,
        uint256 ethReceived,
        uint256 tokensIntoLiqudity
    );
    
    event BuyFeeUpdated (uint16 rewardFee, uint16 marketingFee);
    event SellFeeUpdated (uint16 rewardFee, uint16 marketingFee, uint16 liquidityFee);
    event SwapTokensAmountUpdated(uint256 swapAmount);
    event MaxTxAmountUpdated (uint256 newMaxTxAmount);
    event MaxWalletAmountUpdated (uint256 newMaxWalletAmount);
    event SendDividends(uint256 tokensSwapped, uint256 amount);

    event ProcessedDividendTracker(
        uint256 iterations,
        uint256 claims,
        uint256 lastProcessedIndex,
        bool indexed automatic,
        uint256 gas,
        address indexed processor
    );

    constructor() ERC20("AIG", "AIG") {
        dividendTracker = new TOKENDividendTracker();

        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(
            0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D //Uniswap V2 router
        );
        // Create a uniswap pair for this new token
        address _uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())
            .createPair(address(this), _uniswapV2Router.WETH());

        uniswapV2Router = _uniswapV2Router;
        uniswapV2Pair = _uniswapV2Pair;
       

        buyFee.reward = 5;
        buyFee.marketing = 1;
        totalBuyFee = buyFee.reward + buyFee.marketing;

        sellFee.reward = 7;
        sellFee.marketing = 1;
        sellFee.autoLP = 1;
        totalSellFee = sellFee.reward + sellFee.marketing + sellFee.autoLP;

        coolDownBlocks = 3;

        _setAutomatedMarketMakerPair(_uniswapV2Pair, true);

        // exclude from receiving dividends
        dividendTracker.excludeFromDividends(address(dividendTracker));
        dividendTracker.excludeFromDividends(address(this));
        dividendTracker.excludeFromDividends(owner());
        dividendTracker.excludeFromDividends(DEAD_WALLET);
        dividendTracker.excludeFromDividends(address(_uniswapV2Router));

        // exclude from paying fees or having max transaction amount
        excludeFromFees(owner(), true);
        excludeFromFees(marketingWallet, true);
        excludeFromFees(DEAD_WALLET, true);
        excludeFromFees(address(this), true);

        /*
            _mint is an internal function in ERC20.sol that is only called here,
            and CANNOT be called ever again
        */
        _mint(owner(), 3e9 * 1e9);//3 billion tokens (9 decimals)

        maxTxAmount = totalSupply() / 100; // 1% of the supply per transaction
        maxWallet = totalSupply() / 100 ;// 1% of the supply per wallet limit
        
    }

    receive() external payable {}

    function decimals () public pure override returns (uint8) {
        return 9;
    }

    ///@dev update cooldown blocks b/w buy/sell
    ///@param newCooldown: new cooldown blocks
    function updateCoolDownBlocks (uint256 newCooldown) external onlyOwner {
        require (newCooldown <= MAX_COOLDOWN_BLOCKS, "must be less than max limit");
        coolDownBlocks = newCooldown;
        emit CoolDownBlocksUpdated(newCooldown);
    }

 
    ///@dev update router address to new one
    ///@param newAddress: owner can update the router address
    function updateRouter(address newAddress) external onlyOwner {
        require(newAddress != address(uniswapV2Router), "AIG: The router already has that address");
            address oldRouter = address(uniswapV2Router);
            uniswapV2Router = IUniswapV2Router02(newAddress);
         address get_pair =
            IUniswapV2Factory(uniswapV2Router.factory()).getPair(address(this),
            uniswapV2Router.WETH());
        if (get_pair == address(0)) {
          uniswapV2Pair =
            IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this),
             uniswapV2Router.WETH());
        } else {
        uniswapV2Pair = get_pair;
        }
        emit UpdateUniswapV2Router(newAddress, oldRouter);
    }

    ///@notice claim stucked tokens or eth
    ///@param token: owner can claim stucked tokens/eth from the contract
    function claimStuckTokens(address token) external onlyOwner {
        require(token != address(this),"AIG: can't claim native token");
        if (token == address(0x0)) {
            payable(owner()).transfer(address(this).balance);
            return;
        }
        IERC20 erc20token = IERC20(token);
        uint256 balance = erc20token.balanceOf(address(this));
        require(erc20token.transfer(owner(), balance));
    }
    
    ///@dev manage addresses in fee list
    ///@param account: address to be included or excluded
    ///@param excluded: bool value (true means excluded, false means included)
    function excludeFromFees(address account, bool excluded) public onlyOwner {
        if(excluded){
        require(
            _isExcludedFromFees[account] != excluded,"AIG: Account is already excluded");
        }
        _isExcludedFromFees[account] = excluded;

        emit ExcludeFromFees(account, excluded);
    }

    ///@dev update marketing and liquidity wallet if required
    ///@param marketing: new marketing address
    ///@param liquidity: new liquidity address
    function setWallets(address payable marketing, address payable liquidity ) external onlyOwner {
        require(marketing != address(0) && liquidity != address(0) , "AIG: marketing and lp wallet can't be a zero address");
        marketingWallet = marketing;
        lpWallet = liquidity;

        emit WalletsUpdated(marketing, liquidity);
    }

    ///@dev update the buy fees
    ///@param reward: new reward fee
    ///@param marketing: new marketing fee
    function setBuyFees(
        uint16 reward,
        uint16 marketing
    ) external onlyOwner {
        buyFee.reward = reward;
        buyFee.marketing = marketing;
       

        totalBuyFee = buyFee.reward + buyFee.marketing;
        require (totalBuyFee <=10, "AIG: Max buy fees limit is 10 percent");
        emit BuyFeeUpdated (reward, marketing);
    }
     
    ///@dev update the sell fees
    ///@param reward: new reward fee
    ///@param marketing: new marketing fee
    ///@param autoLP: new liquidity fee
    function setSellFees(
        uint16 reward,
        uint16 marketing,
        uint16 autoLP
    ) external onlyOwner {
        sellFee.reward = reward;
        sellFee.marketing = marketing;
        sellFee.autoLP = autoLP;

        totalSellFee = sellFee.reward + sellFee.marketing + sellFee.autoLP;
        require(totalSellFee <= 10, "AIG: Max Sell fees limit is 10 percent");

        emit SellFeeUpdated(reward, marketing, autoLP);
    }

    ///@dev add or remove new pairs
    ///@param pair: new pair address 
    ///@param value: boolean value, true means added, false means removed
    function setAutomatedMarketMakerPair(address pair, bool value)
        public
        onlyOwner
    {
        require(
            pair != uniswapV2Pair,
            "AIG: The Uniswap pair cannot be removed from automatedMarketMakerPairs"
        );

        _setAutomatedMarketMakerPair(pair, value);
    }

    ///@dev set threshold to swap tax for eth/paxg
    ///@param amount: number of tokens
    function setSwapTokens(uint256 amount) external onlyOwner {
        require (amount <= 3e5, "amount should be less than equal to 0.01% of the supply");
        swapTokensAtAmount = amount * 1e9;
        emit SwapTokensAmountUpdated (swapTokensAtAmount);
    }

    ///@dev check the input pair, if it's valid or not 
    //and return bool value accordingly
    //@param possiblyPair: pair address
    function _checkPairValidity( address possiblyPair)
        internal
        view
        returns (bool isPair)
    {
        address tokenZero = IUniswapV2Pair(possiblyPair).token0();
        address tokenOne = IUniswapV2Pair(possiblyPair).token1();
        if( tokenZero == address(this) || tokenOne == (address(this))){
            return true;
        } 
            return false;
        
    }

    ///@notice private function to which set automated market maker (pair)
    function _setAutomatedMarketMakerPair(address pair, bool value) private {
        require(
            automatedMarketMakerPairs[pair] != value,
            "AIG: Automated market maker pair is already set to that value"
        );

         if(value){
           require ( _checkPairValidity(pair) == value, "Invalid Pair");
        }
        automatedMarketMakerPairs[pair] = value;

        if (value) {
            dividendTracker.excludeFromDividends(pair);
        }

        emit SetAutomatedMarketMakerPair(pair, value);
    }
    
    ///@dev update the gas to reward distribution
    ///@param newValue: set new gas value b/w 200000 to 500000
    function updateGasForProcessing(uint256 newValue) public onlyOwner {
        require(
            newValue >= 200000 && newValue <= 500000,
            "AIG: gasForProcessing must be between 200,000 and 500,000"
        );
        require(
            newValue != gasForProcessing,
            "AIG: Cannot update gasForProcessing to same value"
        );
        emit GasForProcessingUpdated(newValue, gasForProcessing);
        gasForProcessing = newValue;
    }

    ///@dev update minimum claim wait
    ///@param claimWait: update min time b/w two consequtive distribuiton to a wallet
    function updateClaimWait(uint256 claimWait) external onlyOwner {
        dividendTracker.updateClaimWait(claimWait);
    }

    ///@notice Returns claim wait
    function getClaimWait() external view returns (uint256) {
        return dividendTracker.claimWait();
    }

    ///@notice Returns total dividends amount distributed till now
    function getTotalDividendsDistributed() external view returns (uint256) {
        return dividendTracker.totalDividendsDistributed();
    }

    ///@notice Returns if a address is excluded or not from fees
    function isExcludedFromFees(address account) public view returns (bool) {
        return _isExcludedFromFees[account];
    }

    ///@notice returns claimable amount of user
    function withdrawableDividendOf(address account)
        public
        view
        returns (uint256)
    {
        return dividendTracker.withdrawableDividendOf(account);
    }

    ///@notice return dividend token balance of account
    function dividendTokenBalanceOf(address account)
        public
        view
        returns (uint256)
    {
        return dividendTracker.balanceOf(account);
    }

    ///@dev exclude certain wallets or bots from dividends
    ///@param account: owner can exclude certain wallets from dividends
    function excludeFromDividends(address account) external onlyOwner {
        dividendTracker.excludeFromDividends(account);
    }

    function getAccountDividendsInfo(address account)
        external
        view
        returns (
            address,
            int256,
            int256,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256
        )
    {
        return dividendTracker.getAccount(account);
    }

    function getAccountDividendsInfoAtIndex(uint256 index)
        external
        view
        returns (
            address,
            int256,
            int256,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256
        )
    {
        return dividendTracker.getAccountAtIndex(index);
    }

    function processDividendTracker(uint256 gas) external {
        (
            uint256 iterations,
            uint256 claims,
            uint256 lastProcessedIndex
        ) = dividendTracker.process(gas);

        emit ProcessedDividendTracker(
            iterations,
            claims,
            lastProcessedIndex,
            false,
            gas,
            tx.origin
        );
    }

    ///@notice claim the pending rewards manually
    function claim() external {
        dividendTracker.processAccount(payable(msg.sender), false);
    }

    ///@notice returns how many holders have been processed
    function getLastProcessedIndex() external view returns (uint256) {
        return dividendTracker.getLastProcessedIndex();
    }

    ///@notice returns total number of dividend holders
    function getNumberOfDividendTokenHolders() external view returns (uint256) {
        return dividendTracker.getNumberOfTokenHolders();
    }

   
    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal override {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");
        if (amount == 0) {
            super._transfer(from, to, 0);
            return;
        }

        uint256 contractTokenBalance = balanceOf(address(this));

        bool canSwap = contractTokenBalance >= swapTokensAtAmount;

        if (
            canSwap &&
            !swapping &&
            !automatedMarketMakerPairs[from] &&
            from != owner() &&
            to != owner()
        ) {
            swapping = true;
           
            
            swapAndLiquify(contractTokenBalance); 
            if(address(this).balance > 0){
            swapForPAXG(address(this).balance);
            }

            swapping = false;
        }

        bool takeFee = !swapping;

        // if any account belongs to _isExcludedFromFee account then remove the fee
        if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
            takeFee = false;
        }

        if (takeFee) {
           
            require(amount <= maxTxAmount,"AIG: Amount exceeds transfer per transaction limit");
            if (!automatedMarketMakerPairs[to]) {
                require(
                    balanceOf(to) + amount <= maxWallet,
                    "AIG: Balance exceeds Max Wallet limit"
                );
            }
             uint256 fees = 0;
            if (automatedMarketMakerPairs[from]) {
                require(block.number >= _lastTradeBlock[to] + coolDownBlocks, "Cooldown Enabled");
                fees = amount.mul(totalBuyFee).div(100);
                _lastTradeBlock[to] = block.number;
                
            } else if (automatedMarketMakerPairs[to]) {
                require(block.number >= _lastTradeBlock[from] + coolDownBlocks, "Cooldown Enabled");
                fees = amount.mul(totalSellFee).div(100);
                _lastTradeBlock[from] = block.number;
            }

            if (fees > 0) {
                amount = amount.sub(fees);
                super._transfer(from, address(this), fees);
            }
        }

        super._transfer(from, to, amount);

        try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
        try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}

        if (!swapping) {
            uint256 gas = gasForProcessing;

            try dividendTracker.process(gas) returns (
                uint256 iterations,
                uint256 claims,
                uint256 lastProcessedIndex
            ) {
                emit ProcessedDividendTracker(
                    iterations,
                    claims,
                    lastProcessedIndex,
                    true,
                    gas,
                    tx.origin
                );
            } catch {}
        }
    }

    ///@dev set maxTx amount
    ///@param amount: owner set new maxTx amount (must be greator than equals to 1 percent of the supply)
    function setMaxTx (uint256 amount) external onlyOwner {
        require(amount >= (totalSupply().mul(10).div(1000)),"AIG: can't set lower than 1 percent of supply");
        maxTxAmount = amount;
        emit MaxTxAmountUpdated(maxTxAmount);
    }
    
    ///@dev set maxWallet amount
    ///@param amount: owner set new maxWallet amount (must be greator than equals to 1 percent of the supply)
    function setMaxWallet (uint256 amount) external onlyOwner {
        require (amount >= (totalSupply().mul(10).div(1000)),"AIG: Max Wallet limit should be greator than equal to 1%");
        maxWallet = amount;
        emit MaxWalletAmountUpdated(maxWallet);
    }
    
    ///@notice private function which swap the tax for eth, paxg, add liquidity
    function swapAndLiquify(uint256 tokens) private {
        uint256 initialBalance = address(this).balance;
        uint256 totalFee = totalBuyFee + totalSellFee;
        //instead of doing sellFee.autoLP / 2, We multiply the 2 with total fee
        //it saves us from rounding off error, when sellFee.autoLP is greator than 0 
        uint256 feeMultiplier = totalFee * 2 ; 

        if (totalFee == 0 ) {
             super._transfer(address(this), marketingWallet, tokens);
        }
     
        uint256 newBalance = 0;
        uint256 rewardPart = 0;
        uint256 lpPart = 0;
        uint256 lpTokens = 0;

        if (totalFee > 0){
           if(sellFee.autoLP == 0){
               swapTokensForETH(tokens);
                      newBalance = address(this).balance - initialBalance;
                      rewardPart = (newBalance * (buyFee.reward + sellFee.reward)) / totalFee;
           } 

           if(sellFee.autoLP > 0){    
                      lpTokens = (tokens * sellFee.autoLP) / feeMultiplier;
              uint256 swapTokens = tokens - lpTokens;
                      swapTokensForETH(swapTokens);
                      newBalance = address(this).balance - initialBalance;
                      lpPart = (newBalance * sellFee.autoLP) / feeMultiplier;
                      rewardPart = (newBalance * (buyFee.reward + sellFee.reward)) / feeMultiplier;
            }

           if(lpPart > 0 && sellFee.autoLP > 0){                                        
                addLiquidity(lpTokens, lpPart);
                emit SwapAndLiquify(tokens, newBalance, lpTokens);
            }
            //sending all eth to marketing wallet (except reward part)
             uint256 marketingPart = address(this).balance - rewardPart;
            if(marketingPart > 0){
            bool sent;
            (sent,)= marketingWallet.call{value: marketingPart}("");
           }
        } 
    }    

    function addLiquidity(uint256 tokenAmount, uint256 ethAmount) private {

        // approve token transfer to cover all possible scenarios
        _approve(address(this), address(uniswapV2Router), tokenAmount);

        // add the liquidity
        uniswapV2Router.addLiquidityETH{value: ethAmount}(
            address(this),
            tokenAmount,
            0, // slippage is unavoidable
            0, // slippage is unavoidable
            lpWallet,
            block.timestamp
        );

    }

    function swapTokensForETH(uint256 tokenAmount) private {
        // generate the uniswap pair path of token -> weth
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();

        _approve(address(this), address(uniswapV2Router), tokenAmount);

        // make the swap
        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount,
            0, // accept any amount of ETH
            path,
            address(this),
            block.timestamp
        );
    }

    function swapETHForPAXG(uint256 tokenAmount) private {
        address[] memory path = new address[](2);
        path[0] = uniswapV2Router.WETH();
        path[1] = PAXG;

        // make the swap
        uniswapV2Router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: tokenAmount}(
            0,
            path,
            address(this),
            block.timestamp
        );
    }

    function swapForPAXG(uint256 tokens) private {
        uint256 initialPAXGBalance = IERC20(PAXG).balanceOf(address(this));

        swapETHForPAXG(tokens);

        uint256 newBalance = (IERC20(PAXG).balanceOf(address(this))).sub(
            initialPAXGBalance
        );

        bool success = IERC20(PAXG).transfer(
            address(dividendTracker),
            (newBalance)
        );

        if (success) {
            dividendTracker.distributePAXGDividends(newBalance);
            emit SendDividends(tokens, newBalance);
        }
    }
}

contract TOKENDividendTracker is Ownable, DividendPayingToken {
    using SafeMath for uint256;
    using SafeMathInt for int256;
    using IterableMapping for IterableMapping.Map;

    IterableMapping.Map private tokenHoldersMap;
    uint256 public lastProcessedIndex;

    mapping(address => bool) public excludedFromDividends;

    mapping(address => uint256) public lastClaimTimes;

    uint256 public claimWait;
    uint256 public immutable minimumTokenBalanceForDividends;

    event ExcludeFromDividends(address indexed account);
    event ClaimWaitUpdated(uint256 indexed newValue, uint256 indexed oldValue);

    event Claim(
        address indexed account,
        uint256 amount,
        bool indexed automatic
    );

    constructor()
        DividendPayingToken("AIG_Dividend_Tracker", "AIG_dividend_Tracker")
    {
        claimWait = 3600;
        minimumTokenBalanceForDividends = 1000 * (10**9); //must hold 1000+ tokens
    }

    function _transfer(
        address,
        address,
        uint256
    ) internal pure override {
        require(false, "AIG_Dividend_Tracker: No transfers allowed");
    }

    function withdrawDividend() public pure override {
        require(
            false,
            "AIG_Dividend_Tracker: withdrawDividend disabled. Use the 'claim' function on the main TOKEN contract."
        );
    }

    function excludeFromDividends(address account) external onlyOwner {
        require(!excludedFromDividends[account]);
        excludedFromDividends[account] = true;

        _setBalance(account, 0);
        tokenHoldersMap.remove(account);

        emit ExcludeFromDividends(account);
    }

    function updateClaimWait(uint256 newClaimWait) external onlyOwner {
        require(
            newClaimWait >= 3600 && newClaimWait <= 86400,
            "AIG_Dividend_Tracker: claimWait must be updated to between 1 and 24 hours"
        );
        require(
            newClaimWait != claimWait,
            "AIG_Dividend_Tracker: Cannot update claimWait to same value"
        );
        emit ClaimWaitUpdated(newClaimWait, claimWait);
        claimWait = newClaimWait;
    }

    function getLastProcessedIndex() external view returns (uint256) {
        return lastProcessedIndex;
    }

    function getNumberOfTokenHolders() external view returns (uint256) {
        return tokenHoldersMap.keys.length;
    }

    function getAccount(address user)
        public
        view
        returns (
            address account,
            int256 index,
            int256 iterationsUntilProcessed,
            uint256 withdrawableDividends,
            uint256 totalDividends,
            uint256 lastClaimTime,
            uint256 nextClaimTime,
            uint256 secondsUntilAutoClaimAvailable
        )
    {
        account = user;

        index = tokenHoldersMap.getIndexOfKey(account);

        iterationsUntilProcessed = -1;

        if (index >= 0) {
            if (uint256(index) > lastProcessedIndex) {
                iterationsUntilProcessed = index.sub(
                    int256(lastProcessedIndex)
                );
            } else {
                uint256 processesUntilEndOfArray = tokenHoldersMap.keys.length >
                    lastProcessedIndex
                    ? tokenHoldersMap.keys.length.sub(lastProcessedIndex)
                    : 0;

                iterationsUntilProcessed = index.add(
                    int256(processesUntilEndOfArray)
                );
            }
        }

        withdrawableDividends = withdrawableDividendOf(account);
        totalDividends = accumulativeDividendOf(account);

        lastClaimTime = lastClaimTimes[account];

        nextClaimTime = lastClaimTime > 0 ? lastClaimTime.add(claimWait) : 0;

        secondsUntilAutoClaimAvailable = nextClaimTime > block.timestamp
            ? nextClaimTime.sub(block.timestamp)
            : 0;
    }

    function getAccountAtIndex(uint256 index)
        public
        view
        returns (
            address,
            int256,
            int256,
            uint256,
            uint256,
            uint256,
            uint256,
            uint256
        )
    {
        if (index >= tokenHoldersMap.size()) {
            return (
                0x0000000000000000000000000000000000000000,
                -1,
                -1,
                0,
                0,
                0,
                0,
                0
            );
        }

        address account = tokenHoldersMap.getKeyAtIndex(index);

        return getAccount(account);
    }

    function canAutoClaim(uint256 lastClaimTime) private view returns (bool) {
        if (lastClaimTime > block.timestamp) {
            return false;
        }

        return block.timestamp.sub(lastClaimTime) >= claimWait;
    }

    function setBalance(address payable account, uint256 newBalance)
        external
        onlyOwner
    {
        if (excludedFromDividends[account]) {
            return;
        }

        if (newBalance >= minimumTokenBalanceForDividends) {
            _setBalance(account, newBalance);
            tokenHoldersMap.set(account, newBalance);
        } else {
            _setBalance(account, 0);
            tokenHoldersMap.remove(account);
        }

        processAccount(account, true);
    }

    function process(uint256 gas)
        public
        returns (
            uint256,
            uint256,
            uint256
        )
    {
        uint256 numberOfTokenHolders = tokenHoldersMap.keys.length;

        if (numberOfTokenHolders == 0) {
            return (0, 0, lastProcessedIndex);
        }

        uint256 _lastProcessedIndex = lastProcessedIndex;

        uint256 gasUsed = 0;

        uint256 gasLeft = gasleft();

        uint256 iterations = 0;
        uint256 claims = 0;

        while (gasUsed < gas && iterations < numberOfTokenHolders) {
            _lastProcessedIndex++;

            if (_lastProcessedIndex >= tokenHoldersMap.keys.length) {
                _lastProcessedIndex = 0;
            }

            address account = tokenHoldersMap.keys[_lastProcessedIndex];

            if (canAutoClaim(lastClaimTimes[account])) {
                if (processAccount(payable(account), true)) {
                    claims++;
                }
            }

            iterations++;

            uint256 newGasLeft = gasleft();

            if (gasLeft > newGasLeft) {
                gasUsed = gasUsed.add(gasLeft.sub(newGasLeft));
            }

            gasLeft = newGasLeft;
        }

        lastProcessedIndex = _lastProcessedIndex;

        return (iterations, claims, lastProcessedIndex);
    }

    function processAccount(address payable account, bool automatic)
        public
        onlyOwner
        returns (bool)
    {
        uint256 amount = _withdrawDividendOfUser(account);

        if (amount > 0) {
            lastClaimTimes[account] = block.timestamp;
            emit Claim(account, amount, automatic);
            return true;
        }

        return false;
    }
}
